CREATE TABLE IF NOT EXISTS psc_items ( issue_id TEXT PRIMARY KEY, issue_key TEXT NOT NULL, project_key TEXT NOT NULL, org TEXT, summary TEXT, issuetype TEXT, status TEXT, done INTEGER NOT NULL DEFAULT 0, priority TEXT, assignee_id TEXT, assignee_name TEXT, reporter_name TEXT, reporter_team INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT, resolved_at TEXT, team_first_at TEXT, team_first_by TEXT, team_first_how TEXT, team_last_at TEXT, team_last_by TEXT, team_last_what TEXT, customer_last_at TEXT, customer_last_by TEXT, timeline TEXT, synced_at TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS idx_psc_items_open ON psc_items(done, created_at);
CREATE TABLE IF NOT EXISTS psc_actions ( id INTEGER PRIMARY KEY AUTOINCREMENT, issue_id TEXT NOT NULL, issue_key TEXT NOT NULL, account_id TEXT, name TEXT, action TEXT NOT NULL, at TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS idx_psc_actions_issue ON psc_actions(issue_id);
CREATE TABLE IF NOT EXISTS psc_writes ( id INTEGER PRIMARY KEY AUTOINCREMENT, issue_key TEXT NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, label TEXT, attempts INTEGER NOT NULL DEFAULT 0, error TEXT, created_by TEXT, created_at TEXT NOT NULL, done_at TEXT );
